-- name: ConsultationHistory :one
WITH input AS (SELECT $1::integer AS user_id, $2::text AS search, $3::text AS status), owned AS (SELECT r.id,r.problem_ownership,r.owner_name,r.problem_category,r.problem_description,r.handling_technic,r.status,
       r.created_at,r.created_at AS sort_date,r.counselor_id,
       (input.search='' OR strpos(lower(coalesce(r.problem_category,'')),input.search)>0
        OR strpos(lower(coalesce(r.problem_description,'')),input.search)>0
        OR strpos(lower(coalesce(r.handling_technic,'')),input.search)>0
        OR strpos(lower(coalesce(r.owner_name,'')),input.search)>0) AS search_match
       FROM ruang_curhats r,input WHERE r.user_id=input.user_id),
      filtered AS (SELECT owned.* FROM owned, input WHERE search_match AND (input.status='' OR owned.status::text=input.status)),
      page AS (SELECT * FROM filtered ORDER BY sort_date DESC NULLS LAST,id DESC LIMIT $4::bigint OFFSET $5::bigint)
     SELECT COALESCE((SELECT jsonb_agg((to_jsonb(p)-'sort_date'-'search_match'-'counselor_id') || jsonb_build_object('adminUser',CASE WHEN counselor.id IS NULL THEN NULL ELSE jsonb_build_object('display_name',counselor.display_name,'email',counselor.email) END) ORDER BY p.sort_date DESC NULLS LAST,p.id DESC) FROM page p LEFT JOIN admin_users counselor ON counselor.id=p.counselor_id), '[]'::jsonb)::jsonb AS items,
       (SELECT count(*) FROM filtered) AS total,
       (SELECT jsonb_build_object('total',count(*)) FROM owned)::jsonb AS summary;

-- name: AchievementHistory :one
WITH input AS (SELECT $1::integer AS user_id, $2::text AS search, $3::text AS status), owned AS (SELECT a.id,a.name,a.description,to_char(a.achievement_date,'YYYY-MM-DD') AS achievement_date,a.type,a.score,a.proof,a.status,a.remark,
       a.achievement_date AS sort_date,(input.search='' OR strpos(lower(coalesce(a.name,'')),input.search)>0) AS search_match
       FROM achievements a,input WHERE a.user_id=input.user_id),
      filtered AS (SELECT owned.* FROM owned, input WHERE search_match AND (input.status='' OR owned.status::text=input.status)),
      page AS (SELECT * FROM filtered ORDER BY sort_date DESC NULLS LAST,id DESC LIMIT $4::bigint OFFSET $5::bigint)
     SELECT COALESCE((SELECT jsonb_agg(to_jsonb(p)-'sort_date'-'search_match' ORDER BY p.sort_date DESC NULLS LAST,p.id DESC) FROM page p ), '[]'::jsonb)::jsonb AS items,
       (SELECT count(*) FROM filtered) AS total,
       (SELECT jsonb_build_object('total',count(*),'points',coalesce(sum(score) FILTER (WHERE status=1),0),'pending',count(*) FILTER (WHERE status=0)) FROM owned)::jsonb AS summary;
